      let lobe = loEllipse(q - vec2f(-0.25, 0.12), vec2f(0.19, 0.18) * mediumSize);
      d = loSmoothUnion(body, lobe, 0.09);
      let cleft = loEllipse(q - vec2f(0.21, -0.10), vec2f(0.14, 0.16) * (0.75 + concavity * 0.20));
      d = loSmoothSubtract(d, cleft, 0.040);
